    "error": {
        "message": "Rate limit reached for gpt-5.4-mini in organization org-4bwAKc06DQ01SyQWGdOSFIy1 on requests per day (RPD): Limit 50, Used 50, Requested 1. Please try again in 28m48s. Visit https://platform.openai.com/account/rate-limits to learn more. You can increase your rate limit by adding a payment method to your account at https://platform.openai.com/account/billing.",
        "type": "requests",
        "param": null,
        "code": "rate_limit_exceeded"
    }
}
"}
assert 500 == 200
 +  where 500 = <Response [500]>.status_code

